INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE code = 'NG';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & clearance mechanics', '[["Schema", "FIRS e-invoice schema following UBL / Peppol BIS Billing 3.0 conventions; submitted as XML or JSON"], ["Clearance", "B2B/B2G invoices validated by the platform BEFORE delivery to the buyer (pre-clearance)"], ["Stamping", "Unique Invoice Reference Number (IRN) + Cryptographic Stamp Identifier (CSID) per cleared invoice; QR code for verifying printed/PDF renderings"], ["B2C", "Reported to the platform within 24 hours of issuance rather than pre-cleared"], ["Buyer duty", "Buyers are expected to verify inbound invoices carry valid IRNs"]]', 'A reported ~55 mandatory data fields and a PDF/A-3-with-embedded-XML option appear in one industry briefing only -- treat as plausible. EY describes the exchange layer as a Peppol four-corner model with tax-authority clearance on top.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE code = 'NG';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Legal & institutional framework', '[["Platform", "Merchant Buyer Solution (FIRSMBS), announced late 2024, unveiled 29 Apr 2025"], ["Statutory basis", "FIRS Establishment Act powers pre-2026; Nigeria Tax Administration Act 2025 (ss. 23, 103, 144, 200) and Nigeria Tax Act 2025 (ss. 104, 158) from 1 Jan 2026"], ["Authority", "FIRS renamed the Nigeria Revenue Service (NRS) from 1 Jan 2026, under the four tax reform acts signed 26 Jun 2025"], ["Technical guideline", "NITDA National Regulatory Guideline for Electronic Invoicing, effective 1 Sep 2025"], ["Peppol governance", "NRS is the national Peppol Authority (listed 26 Sep 2025); Nigeria''s TIN registered under ISO/IEC 6523"]]', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE code = 'NG';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Who must comply, and when', '[["Large (>= NGN 5bn turnover)", "Live 1 Aug 2025; deadline extended to 1 Nov 2025; hard final deadline 31 Jul 2026, enforcement from August 2026"], ["Medium (NGN 1-5bn)", "Pilot Apr-Jun 2026; mandatory from 1 Jul 2026; penalty soft-landing until enforcement Jan-Mar 2027"], ["Emerging/small (< NGN 1bn)", "Mandatory from 1 Jul 2027; enforcement from Jan-Mar 2028"], ["Micro (< NGN 50m)", "Exempt -- below Nigeria''s VAT registration threshold"], ["Transaction coverage", "B2B, B2G (pre-clearance) and B2C (24-hour reporting), for VAT-taxable supplies including cross-border"]]', NULL, NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 1, 'pills' FROM countries WHERE code = 'NG';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The clearance flow', 'A compliant Nigerian B2B/B2G invoice moves through this sequence:', 'An invoice issued outside the MBS carries real consequences on both sides: the issuer faces the NGN 200,000 + 100%-of-tax penalty, and the buyer loses the input-VAT credit.');
