INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 3, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Cleared invoice delivers to the buyer, who verifies the IRN');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 4, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'B2C sales route differently: reported to the platform within 24 hours of issuance');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE code = 'NG';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Statutory penalties (NTAA 2025, enforceable from 1 Jan 2026)', '[["Processing taxable supplies outside the fiscalisation system", "NGN 200,000 + 100% of the tax due + interest at the CBN Monetary Policy Rate"], ["Refusing technology-deployment access after statutory notice", "NGN 1,000,000 on the first day + NGN 10,000 per day thereafter"], ["Buyer-side consequence", "Input-VAT credit denied on invoices issued outside the MBS"]]', 'Professional-services sources state the interest reference slightly differently (CBN MPR vs MPR + 2% per EY) -- the base penalty amounts are consistently reported across Mondaq/WTS, EY and industry trackers.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE code = 'NG';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Enforcement timeline', '[["Large taxpayers", "Compliance monitoring and enforcement actions from August 2026 (after the 31 Jul 2026 hard deadline)"], ["Medium taxpayers", "Soft-landing until the Jan-Mar 2027 enforcement window"], ["Emerging/small", "Enforcement from the Jan-Mar 2028 window"], ["Adoption so far", "~1,000 of ~5,000 targeted large taxpayers onboarded in the first two weeks (Aug 2025); \"over 1,000 companies\" compliant as of Q1 2026 (NRS chairman)"]]', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE code = 'NG';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔍 What we could not confirm', '[["72-hour buyer rejection window", "Reported by one tracker only -- treat as plausible"], ["B2C late-reporting penalty (NGN 50,000/day)", "Industry-reported; not seen in an official notice this round"], ["Archiving period", "Sources conflict: 5-6 years (10 for cross-border) with in-Nigeria data localization vs 6 years standard / 7 on request -- unresolved"], ["Expense-deduction denial for non-MBS invoices", "Single-source; the input-VAT denial is the confirmed buyer-side consequence"], ["Direct platform access", "One source says all production traffic must route via certified SI/APPs; others describe a free direct portal + API -- likely both true by volume tier, but unconfirmed"]]', 'Items here are excluded from the milestone timeline and summary above under this site''s sourcing standard -- listed so you know what to double-check rather than silently omitted.', NULL);
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE code = 'NG';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Sort your Tax ID first', 'Confirm your TIN is valid and complete the migration to the new Tax ID where applicable -- this is the most commonly reported onboarding blocker under the 2026 tax-reform transition.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE code = 'NG';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Register on the e-invoicing portal', 'Onboard at einvoice.firs.gov.ng (email verification required) and confirm which rollout wave your turnover places you in.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE code = 'NG';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Choose a certified provider', 'Select from the NITDA-certified system integrators and access-point providers (16 at launch, including Interswitch, Remita and eTranzact) for production integration via their RESTful APIs -- or use the portal channel for low volumes.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE code = 'NG';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Test in the sandbox, then go live', 'Complete sandbox validation against the NRS guidelines before production cutover -- go-live means live IRN transmission on every B2B/B2G invoice, not just completed registration.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE code = 'NG';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Stand up B2C reporting and verification routines', 'Set up the 24-hour B2C reporting flow, and train AP staff to verify that inbound supplier invoices carry valid IRNs -- an invoice outside the MBS costs you the input-VAT credit.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE code = 'NG';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Archive and monitor', 'Retain cleared invoices and their IRN/CSID records (retention-period sources conflict -- see the note above; 6 years is the conservative floor reported), and watch NRS notices: the phased schedule has already shifted once.');
